    file_path, file_size, content_type
)
VALUES (
    #{caseId}, #{evidenceType}, #{description, jdbcType=VARCHAR}, #{originalFilename},
    #{storedFilename}, #{filePath}, #{fileSize}, #{contentType, jdbcType=VARCHAR}
)

mapper.select:
SELECT id, case_id, evidence_type, description, original_filename, stored_filename,
       file_path, file_size, content_type, case_evidences_analysis_status,
       created_at, updated_at
FROM case_evidences
WHERE case_id = #{caseId}
  AND id = #{evidenceId}

mapper.update:
UPDATE case_evidences
SET case_evidences_analysis_status = 'PROCESSING',
    updated_at = CURRENT_TIMESTAMP
WHERE case_id = #{caseId}
  AND id = #{evidenceId}
  AND case_evidences_analysis_status = 'PENDING'

UPDATE case_evidences
SET case_evidences_analysis_status = 'FAILED',
    updated_at = CURRENT_TIMESTAMP
WHERE case_id = #{caseId}
  AND id = #{evidenceId}
  AND case_evidences_analysis_status = 'PROCESSING'
